    public boolean isPrime(int n) {
        if (n < 2) return false;
        // Only divisors up to sqrt(n) need to be checked; use long to avoid overflow in i * i
        for (long i = 2; i * i <= n; i++) {
            if (n % i == 0) return false;
        }
        return true;
    }
}

